import { PumpTokenDetail } from '@/type/pump'
import { TextWarp } from '@cetus/ui-kit'
import { HTMLChakraProps } from '@chakra-ui/react'

interface NameSymbolBlockProps extends HTMLChakraProps<'div'> {
  tokenDetail: PumpTokenDetail
  haveTooltip?: boolean
}

const NameSymbolBlock = ({ tokenDetail, haveTooltip = true, ...rest }: NameSymbolBlockProps) => {
  return (
    <TextWarp haveTooltip={haveTooltip} {...rest}>
      {tokenDetail?.name}&nbsp;{tokenDetail?.symbol ? `(${tokenDetail?.symbol})` : ''}
    </TextWarp>
  )
}

export default NameSymbolBlock
